{
  "html": "<div data-ui-unit="E2">
  <label for="search" class="search-label">멘토 검색</label>
  <div class="search-surface">
    <img src="assets/reference/search.svg" alt="" class="search-icon" />
    <input type="text" id="search" placeholder="멘토 또는 회사를 검색하세요" disabled />
  </div>
</div>",
  "css": ".search-label {
  display: block;
  font-size: 14px;
  font-weight: 500;
  color: #283548;
  margin-bottom: 8px;
}

.search-surface {
  display: flex;
  align-items: center;
  background-color: #ffffff;
  border-radius: 12px;
  min-height: 46px;
  padding: 0 16px;
}

.search-icon {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  opacity: 0.5;
}

input#search {
  flex: 1;
  min-width: 0;
  background: transparent;
  border: none;
  padding: 0;
  margin-left: 12px;
  color: #283548;
  font-family: inherit;
  font-size: 14px;
}

input#search::placeholder {
  color: #9aa3b0;
}

input#search:focus-visible {
  outline: none;
}"
}
